const inputItem = $input.first();
const rawText = inputItem.json.data || '';

const lines = rawText.split('\n').filter((l) => l.trim().length > 0);
const records = [];
let parseFailures = 0;
for (const line of lines) {
  try { records.push(JSON.parse(line)); } catch (e) { parseFailures++; }
}

const PLACEHOLDER_TEXT = 'unclassified — pending ai extraction';
function isPlaceholder(s) { return String(s || '').trim().toLowerCase() === PLACEHOLDER_TEXT; }
function keywordRegex(term, exact) {
  const escaped = term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return exact ? new RegExp(`\\b${escaped}\\b`, 'i') : new RegExp(`\\b${escaped}\\w*`, 'i');
}

const CAPABILITY_DOMAINS = [
  { domain: 'ai_reasoning_chat_agent', stack: ['Claude', 'Claude Code', 'Anthropic API', 'MCP', 'ChatGPT', 'Grok'],
    keywords: [['ai', true], ['chatbot', false], ['agent', false], ['assistant', false], ['automat', false], ['gpt', true], ['llm', true], ['prompt', false], ['claude', false], ['copilot', false]] },
  { domain: 'workflow_automation', stack: ['n8n', 'MCP'],
    keywords: [['workflow', false], ['automat', false], ['integrat', false], ['zapier', false], ['pipeline', false], ['n8n', true], ['no-code', true], ['low-code', true]] },
  { domain: 'voice_audio_generation', stack: ['ElevenLabs'],
    keywords: [['voice', false], ['audio', false], ['podcast', false], ['speech', false], ['narrat', false], ['tts', true], ['text-to-speech', true]] },
  { domain: 'video_production', stack: ['CapCut'],
    keywords: [['video', false], ['editing', false], ['shorts', false], ['reel', false], ['youtube', false], ['tiktok', false], ['clip', false]] },
  { domain: 'graphic_design_image', stack: ['Canva'],
    keywords: [['design', false], ['graphic', false], ['thumbnail', false], ['banner', false], ['logo', false], ['poster', false], ['flyer', false], ['template', false]] },
  { domain: 'app_software_development', stack: ['Xcode', 'MacBook'],
    keywords: [['ios app', true], ['mobile app', true], ['swift', false], ['app store', true], ['software', false], ['saas', true], ['web app', true], ['website', false]] },
  { domain: 'ai_media_generation', stack: ['KIE.ai'],
    keywords: [['image generation', true], ['ai image', true], ['ai video', true], ['media generation', true], ['generative', false]] },
];

const results = records.map((rec) => {
  const rs = rec.raw_signal || {};
  const title = isPlaceholder(rs.opportunity_title) ? '' : (rs.opportunity_title || '');
  const problem = isPlaceholder(rs.problem) ? '' : (rs.problem || '');
  const demand = isPlaceholder(rs.demand_signal) ? '' : (rs.demand_signal || '');
  const combinedText = `${title} ${problem} ${demand}`;
  const signal_text_available = combinedText.trim().length > 0;

  const matched = [];
  if (signal_text_available) {
    CAPABILITY_DOMAINS.forEach((d) => {
      const hit = d.keywords.some(([term, exact]) => keywordRegex(term, exact).test(combinedText));
      if (hit) matched.push(d);
    });
  }
  const matched_capability_domains = matched.map((d) => d.domain);
  const matched_stack_tools = [...new Set(matched.flatMap((d) => d.stack))];

  let capability_match_status;
  let fulfillment_feasible_now;
  let missing_capability_note;
  let estimated_new_tool_cost;

  if (!signal_text_available) {
    capability_match_status = 'INSUFFICIENT_SIGNAL_TEXT';
    fulfillment_feasible_now = null;
    missing_capability_note = 'No usable free-text signal (title/problem/demand_signal empty or UOR-02 placeholder-only) to match against the stack.';
    estimated_new_tool_cost = null;
  } else if (matched_stack_tools.length > 0) {
    capability_match_status = 'MATCHED_EXISTING_STACK';
    fulfillment_feasible_now = true;
    missing_capability_note = null;
    estimated_new_tool_cost = null;
  } else {
    capability_match_status = 'NO_STACK_MATCH_FOUND';
    fulfillment_feasible_now = false;
    missing_capability_note = 'No existing Section 3 stack keyword matched this opportunity\'s described text. Per Section 9, no new tool is inferred automatically -- requires manual review.';
    estimated_new_tool_cost = 'NOT_DETERMINED -- requires manual review, not estimable by this deterministic rule table';
  }

  const factors = rec.scoring_factors || {};
  const autoEstimateRaw = factors.automation_potential?.estimate;
  const automation_potential_pct = typeof autoEstimateRaw === 'number' ? autoEstimateRaw * 10 : null;

  return {
    opportunity_id: rec.opportunity_id ?? null,
    signal_text_available,
    matched_capability_domains,
    matched_stack_tools,
    capability_match_status,
    fulfillment_feasible_now,
    automation_potential_pct,
    automation_potential_source: automation_potential_pct !== null ? 'uor01_ai_extracted_factor' : null,
    missing_capability_note,
    estimated_new_tool_cost,
    category_excluded_reason: 'UOR-02 placeholder category/normalized_opportunity text excluded from matching -- proven non-discriminative for real records (same issue UOR-03 fixed)',
    capability_matching_formula_version: 'uor05-v1-keyword-stack-2026-09-05',
    computed_at: new Date().toISOString(),
  };
});

const fileText = results.map((r) => JSON.stringify(r)).join('\n') + '\n';

return [{
  json: {
    record_count: results.length,
    parse_failures: parseFailures,
    file_text: fileText,
  },
}];
